import{_ as t,o as a,c as d,a2 as o}from"./chunks/framework.DrWxItG4.js";const u=JSON.parse('{"title":"Dialogs","description":"","frontmatter":{},"headers":[],"relativePath":"guide/dialogs.md","filePath":"guide/dialogs.md"}'),n={name:"guide/dialogs.md"};function s(l,e,i,c,r,p){return a(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="dialogs" tabindex="-1">Dialogs <a class="header-anchor" href="#dialogs" aria-label="Permalink to &quot;Dialogs&quot;">​</a></h1><p><a href="/gtps-guide/functions/OnDialogRequest">OnDialogRequest</a> carries one element per line, <code>|</code>-separated. gurotopia builds them with <code>create_dialog</code> (<code>include/tools/create_dialog.cpp</code>):</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>set_default_color|`o</span></span>\n<span class="line"><span>add_label_with_icon|big|`wDrop Dirt``|left|2|</span></span>\n<span class="line"><span>add_textbox|How many to drop?|left|</span></span>\n<span class="line"><span>add_text_input|count||5|5|</span></span>\n<span class="line"><span>embed_data|itemID|2</span></span>\n<span class="line"><span>end_dialog|drop_item|Cancel|OK|</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Element</th><th>Fields</th></tr></thead><tbody><tr><td><code>add_label</code></td><td>size (<code>big</code> or small), text, align (<code>center</code> or left)</td></tr><tr><td><code>add_label_with_icon</code></td><td>size, text, align, icon item id</td></tr><tr><td><code>add_textbox</code>, <code>add_smalltext</code></td><td>text, align</td></tr><tr><td><code>add_text_input</code></td><td>name, label, default value, max length</td></tr><tr><td><code>add_checkbox</code></td><td>name, label, 0/1</td></tr><tr><td><code>add_button</code></td><td>name, label, flags (<code>off</code> greys it out), 0, 0</td></tr><tr><td><code>add_custom_button</code></td><td>name, <code>key:value;…</code> style settings</td></tr><tr><td><code>add_image_button</code></td><td>name, image, …</td></tr><tr><td><code>embed_data</code></td><td>key, value: sent back unchanged</td></tr><tr><td><code>add_spacer</code></td><td>small / big</td></tr><tr><td><code>end_dialog</code></td><td>dialog name, cancel label, OK label (an empty label hides that button)</td></tr></tbody></table><p>Most elements take one more field at the end: options as <code>key:value;…</code>, for example <code>featureEnableFlag:&lt;n&gt;</code>. The 5.60 client parses about 80 elements. <a href="/gtps-guide/guide/dialog-elements">Dialog elements</a> lists all of them, with their fields and what each sends back.</p><p>Text colors are <code>`x</code> codes (<code>`w</code> white, <code>`2</code> green, <code>`4</code> red, …), and <code>``</code> resets.</p><h2 id="answering" tabindex="-1">Answering <a class="header-anchor" href="#answering" aria-label="Permalink to &quot;Answering&quot;">​</a></h2><p>The client answers with <a href="/gtps-guide/actions/dialog_return">action|dialog_return</a>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>action|dialog_return</span></span>\n<span class="line"><span>dialog_name|drop_item</span></span>\n<span class="line"><span>itemID|2|</span></span>\n<span class="line"><span>count|5</span></span></code></pre></div><ul><li>every <code>embed_data</code> as <code>key|value|</code></li><li><code>buttonClicked|&lt;name&gt;</code> when the player pressed a button added by an element (<code>add_button</code> and the others)</li><li>every text input as <code>name|value</code> (<code>|</code> in the text becomes <code>[</code>), checkboxes as <code>name|0</code> or <code>name|1</code></li></ul><p>The <code>end_dialog</code> OK button sends the answer <strong>without</strong> a <code>buttonClicked</code> line (the example above is one), and its Cancel button sends nothing. The details, including pickers and ratings, are under <a href="/gtps-guide/guide/dialog-elements#what-the-client-sends-back">What the client sends back</a>.</p><p>gurotopia routes it by <code>dialog_name</code> to <code>include/action/dialog_return/</code>.</p>',12)])])}const h=t(n,[["render",s]]);export{u as __pageData,h as default};
